<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<main id="main" class="container inner-page"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class( 'post-detail' ); ?>>
<p class="eyebrow"><a href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php esc_html_e( 'الرئيسية', 'sada-clips' ); ?></a> <span aria-hidden="true">/</span> <?php echo esc_html( get_post_type_object( get_post_type() )->labels->singular_name ); ?></p>
<?php if ( get_post_meta( get_the_ID(), '_sada_sample', true ) ) : ?><p class="sample-label"><?php esc_html_e( 'محتوى تجريبي للتوضيح', 'sada-clips' ); ?></p><?php endif; ?>
<h1><?php echo esc_html( get_the_title() ); ?></h1><?php if ( post_password_required() ) { echo get_the_password_form(); echo '</article>'; continue; } ?><div class="post-meta"><time datetime="<?php echo esc_attr( get_the_date( DATE_W3C ) ); ?>"><?php echo esc_html( get_the_date( 'j / n / Y' ) ); ?></time><span><?php echo esc_html( get_post_meta( get_the_ID(), '_sada_speaker', true ) ?: ( get_post_meta( get_the_ID(), '_sada_credit', true ) ?: __( 'فريق صدى كليبز', 'sada-clips' ) ) ); ?></span>
<?php $duration = get_post_meta( get_the_ID(), '_sada_duration', true ); if ( $duration ) : ?><span><?php echo esc_html( sprintf( __( 'المدة: %s', 'sada-clips' ), $duration ) ); ?></span><?php endif; sada_share(); ?></div>
<div class="card-media"><?php sada_thumbnail( sada_card_kind() === 'program' ? get_post_type() : sada_card_kind() ); ?></div>
<?php if ( in_array( get_post_type(), array( 'clip', 'program' ), true ) ) : ?><div class="video-box"><?php $video = get_post_meta( get_the_ID(), '_sada_video', true ); if ( $video ) { sada_video_embed( $video ); } else { ?><p><?php esc_html_e( 'لم يُضف رابط فيديو لهذا المحتوى بعد.', 'sada-clips' ); ?></p><?php } ?></div><?php endif; ?>
<div class="entry-content"><?php the_content(); wp_link_pages( array( 'before' => '<nav aria-label="' . esc_attr__( 'صفحات المحتوى', 'sada-clips' ) . '">', 'after' => '</nav>' ) ); ?></div>
<?php if ( get_post_type() === 'program' ) : $clips = new WP_Query( array( 'post_type' => 'clip', 'posts_per_page' => 8, 'meta_key' => '_sada_program_id', 'meta_value' => get_the_ID() ) ); if ( $clips->have_posts() ) : ?><section><h2><?php esc_html_e( 'مقاطع هذا البرنامج', 'sada-clips' ); ?></h2><div class="card-grid"><?php while ( $clips->have_posts() ) : $clips->the_post(); get_template_part( 'template-parts/card', 'program' ); endwhile; ?></div></section><?php endif; wp_reset_postdata(); endif; ?>
<nav class="post-links" aria-label="<?php esc_attr_e( 'المحتوى المجاور', 'sada-clips' ); ?>"><?php previous_post_link( '%link', '← %title' ); next_post_link( '%link', '%title →' ); ?></nav>
</article><?php endwhile; ?></main>
